	@Test
	void nativeFilteredSubjectRemovalIncludesApprovedStatementsAndKeepsDriverUsable() {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		Resource firstSubject = vf.createIRI("urn:first-subject");
		Resource secondSubject = vf.createIRI("urn:second-subject");
		IRI firstPredicate = vf.createIRI("urn:first-predicate");
		IRI secondPredicate = vf.createIRI("urn:second-predicate");
		Value firstObject = vf.createIRI("urn:first-object");
		Value secondObject = vf.createIRI("urn:second-object");
		Resource context = vf.createIRI("urn:context");
		SailSourceModel model = getNewModel();
		model.add(firstSubject, firstPredicate, firstObject, context);
		model.add(secondSubject, firstPredicate, secondObject, context);

		Set<Resource> subjects = model.filter(null, null, null, context).subjects();
		Iterator<Resource> iterator = subjects.iterator();
		Resource removedSubject = iterator.next();
		assertThat(iterator.hasNext()).isTrue();

		model.add(removedSubject, secondPredicate, secondObject, context);
		iterator.remove();
		assertThat(iterator.hasNext()).isTrue();
		Resource remainingSubject = iterator.next();
		assertThat(remainingSubject).isNotEqualTo(removedSubject);
		iterator.remove();
		assertThat(iterator.hasNext()).isFalse();

		assertThat(model.contains(removedSubject, firstPredicate, firstObject, context)).isFalse();
		assertThat(model.contains(removedSubject, secondPredicate, secondObject, context)).isFalse();
		assertThat(model.filter(removedSubject, null, null, context)).isEmpty();
		assertThat(model.filter(remainingSubject, null, null, context)).isEmpty();
	}

	@Test
	void nativeFilteredPredicateRemovalHandlesPendingPredicateWithWildcardPattern() {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		Resource subject = vf.createIRI("urn:pending-predicate-subject");
		Resource pendingSubject = vf.createIRI("urn:pending-predicate-pending-subject");
		Resource unrelatedSubject = vf.createIRI("urn:pending-predicate-unrelated-subject");
		IRI firstPredicate = vf.createIRI("urn:pending-predicate-first");
		IRI unrelatedPredicate = vf.createIRI("urn:pending-predicate-unrelated");
		Value firstObject = vf.createIRI("urn:pending-predicate-first-object");
		Value pendingObject = vf.createIRI("urn:pending-predicate-pending-object");
		Value unrelatedObject = vf.createIRI("urn:pending-predicate-unrelated-object");
		Resource context = vf.createIRI("urn:pending-predicate-context");
		SailSourceModel model = getNewModel();
		model.add(subject, firstPredicate, firstObject, context);
		model.add(unrelatedSubject, unrelatedPredicate, unrelatedObject, context);

		Iterator<IRI> predicates = model.filter(null, null, null, context).predicates().iterator();
		IRI returnedPredicate = null;
		while (predicates.hasNext()) {
			IRI candidate = predicates.next();
			if (firstPredicate.equals(candidate)) {
				returnedPredicate = candidate;
				break;
			}
		}
		assertThat(returnedPredicate).isEqualTo(firstPredicate);
		model.add(pendingSubject, firstPredicate, pendingObject, context);
		predicates.remove();

		assertThat(model.filter(null, firstPredicate, null, context)).isEmpty();
		assertThat(model.contains(unrelatedSubject, unrelatedPredicate, unrelatedObject, context)).isTrue();
	}

