	@Test
	@Timeout(value = 10_000, unit = MILLISECONDS)
	void nativeFilteredRemovalCancellationReleasesWriterForNextTransaction() {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		Resource existingSubject = vf.createIRI("urn:cancelled-removal-existing-subject");
		Resource pendingSubject = vf.createIRI("urn:cancelled-removal-pending-subject");
		Resource recoverySubject = vf.createIRI("urn:cancelled-removal-recovery-subject");
		IRI predicate = vf.createIRI("urn:cancelled-removal-predicate");
		IRI pendingPredicate = vf.createIRI("urn:cancelled-removal-pending-predicate");
		IRI recoveryPredicate = vf.createIRI("urn:cancelled-removal-recovery-predicate");
		Value object = vf.createIRI("urn:cancelled-removal-object");
		Value recoveryObject = vf.createIRI("urn:cancelled-removal-recovery-object");
		Resource context = vf.createIRI("urn:cancelled-removal-context");
		SailSourceModel model = getNewModel();
		model.add(existingSubject, predicate, object, context);

		Iterator<Value> objects = model.filter(null, null, object, context).objects().iterator();
		assertThat(objects.next()).isEqualTo(object);
		model.add(pendingSubject, pendingPredicate, object, context);

		Throwable cancellation;
		try {
			Thread.currentThread().interrupt();
			cancellation = catchThrowable(objects::remove);
			assertThat(cancellation).isInstanceOf(ModelException.class);
		} finally {
			Thread.interrupted();
		}

		assertThat(model.add(recoverySubject, recoveryPredicate, recoveryObject, context)).isTrue();
		assertThat(model.contains(existingSubject, predicate, object, context)).isTrue();
		assertThat(model.contains(pendingSubject, pendingPredicate, object, context)).isFalse();
		assertThat(model.contains(recoverySubject, recoveryPredicate, recoveryObject, context)).isTrue();
	}

